		Actor:     store.AuditActor{Type: "api_key", ID: p.KeyID, UserID: p.UserID},
		Target:    store.AuditTarget{Type: targetType, ID: targetID},
		RequestID: RequestID(r.Context()),
		At:        s.clock.Now().UTC(),
	}
	if changes != nil {
		e.Changes = &changes
	}
	s.store.AddAuditEvent(e)
}

// auditChanges returns the fields whose JSON value differs between before and after, each with its old and new value.
// Fields that never enter the log are left out.
func auditChanges(before, after any) map[string]store.AuditChange {
	b, a := jsonFields(before), jsonFields(after)
	changes := map[string]store.AuditChange{}
	for k := range b {
		if !slices.Contains(auditSecrets, k) && !reflect.DeepEqual(b[k], a[k]) {
			changes[k] = store.AuditChange{From: b[k], To: a[k]}
		}
	}
	for k := range a {
		if _, ok := b[k]; !ok && !slices.Contains(auditSecrets, k) {
			changes[k] = store.AuditChange{From: nil, To: a[k]}
		}
	}
	return changes
}

// jsonFields is v as its JSON object: field name to value.
func jsonFields(v any) map[string]any {
	b, _ := json.Marshal(v)
	var m map[string]any
	_ = json.Unmarshal(b, &m)
	return m
}

// listAuditEvents lists the organization's audit entries, newest first, optionally only those of ?action=, ?target_id= or
// ?actor_id= (a user ID or an API key ID). Only owners and admins may read the log.
func (s *Server) listAuditEvents(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "forbidden"})
		return
	}
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	evs := s.store.AuditEvents(p.OrgID, store.AuditFilter{Action: q.Get("action"), TargetID: q.Get("target_id"), ActorID: q.Get("actor_id")})
	items, next := pageOfNewest(evs, auditKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

// pageOfNewest is pageOf for items sorted newest first: the page starts after the cursor, with the items older than it.
func pageOfNewest[T any](items []T, key func(T) cursor, p page) ([]T, string) {
	start := 0
	if p.after != nil {
		start = len(items)
		for i, it := range items {
			if key(it).less(*p.after) {
				start = i
				break
			}
		}
	}
	end := min(start+p.limit, len(items))
	out := items[start:end]
	next := ""
	if end < len(items) && len(out) > 0 {
		next = encodeCursor(key(out[len(out)-1]))
	}
	return out, next
}

