func TestAuditLogAccessAndFilters(t *testing.T) {
	e := apitest.New(t)
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	_, billing := e.AddMember(e.Acme, "billing@acme.example", store.RoleBilling)
	admin, adminKey := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	c1 := e.CreateCustomer(e.Acme, "One", "one@example.com")
	c2 := e.CreateCustomer(e.Acme, "Two", "two@example.com")
	e.CreateCustomer(e.Acme, "Three", "three@example.com")
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", adminKey, map[string]any{"name": "Seat", "currency": "USD", "price": "10.00", "interval": "month"}, nil)

	for _, key := range []string{viewer, billing} {
		r := e.Do("GET", "/v1/audit-events", key, nil)
		if r.Code != http.StatusForbidden || len(r.Map(t)) != 1 || r.Map(t)["error"] != "forbidden" {
			t.Fatalf("non-admin read: %s", r)
		}
	}
	all := readAudit(t, e, adminKey, "")
	if got := len(all.Items); got != 4 {
		t.Fatalf("admin sees %d entries, want 4", got)
	}

	ownerKey := keyIDOf(t, e, e.Acme.Key)
	for _, tc := range []struct {
		query string
		want  int
	}{
		{"?action=customer.created", 3},
		{"?action=plan.created", 1},
		{"?target_id=" + c2.ID, 1},
		{"?actor_id=" + admin.ID, 1},
		{"?actor_id=" + keyIDOf(t, e, adminKey), 1},
		{"?actor_id=" + e.Acme.Owner.ID, 3},
		{"?actor_id=" + ownerKey, 3},
		{"?action=customer.deleted", 0},
	} {
		if got := len(readAudit(t, e, adminKey, tc.query).Items); got != tc.want {
			t.Fatalf("%s: %d entries, want %d", tc.query, got, tc.want)
		}
	}

	first := readAudit(t, e, adminKey, "?limit=3")
	if len(first.Items) != 3 || first.NextCursor == "" {
		t.Fatalf("first page = %d entries, next %q", len(first.Items), first.NextCursor)
	}
	second := readAudit(t, e, adminKey, "?limit=3&cursor="+first.NextCursor)
	if len(second.Items) != 1 || second.NextCursor != "" {
		t.Fatalf("second page = %d entries, next %q", len(second.Items), second.NextCursor)
	}
	if second.Items[0].ID != all.Items[3].ID || first.Items[0].Action != "plan.created" {
		t.Fatalf("pages are not newest first: %v then %v", actionsOf(first), actionsOf(second))
	}
	if got := actionsOf(all)[0]; got != "plan.created" {
		t.Fatalf("newest entry is %q", got)
	}
	if got := readAudit(t, e, adminKey, "?actor_id="+ownerKey+"&action=customer.created"); len(got.Items) != 3 || got.Items[2].Target.ID != c1.ID {
		t.Fatalf("combined filter = %+v", got)
	}
}

package api_test

import (
	"net/http"
	"reflect"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// auditLog is one page of GET /v1/audit-events.
type auditLog struct {
	Items      []store.AuditEvent `json:"items"`
	NextCursor string             `json:"next_cursor"`
}

func readAudit(t *testing.T, e *apitest.Env, key, query string) auditLog {
	t.Helper()
	var log auditLog
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, key, nil, &log)
	return log
}

func actionsOf(log auditLog) []string {
	out := []string{}
	for _, ev := range log.Items {
		out = append(out, ev.Action)
	}
	return out
}

// changedFields is the names of the fields an entry says changed.
func changedFields(ev store.AuditEvent) []string {
	out := []string{}
	if ev.Changes != nil {
		for k := range *ev.Changes {
			out = append(out, k)
		}
	}
	return out
}

func keyIDOf(t *testing.T, e *apitest.Env, token string) string {
	t.Helper()
	k, ok := e.Store.APIKeyByToken(token)
	if !ok {
		t.Fatalf("no key for token")
	}
	return k.ID
}

// doWithID sends a request with X-Request-Id: requestID and checks the status.
func doWithID(t *testing.T, e *apitest.Env, want int, method, path, key, requestID string, body any) *apitest.Response {
	t.Helper()
	r := e.DoWith(method, path, key, body, http.Header{"X-Request-Id": {requestID}})
	if r.Code != want {
		t.Fatalf("%s %s: want %d, got %s", method, path, want, r)
	}
	return r
}

func TestAuditLogRecordsWrites(t *testing.T) {
	e := apitest.New(t)
	var c store.Customer
	doWithID(t, e, http.StatusCreated, "POST", "/v1/customers", e.Acme.Key, "req-create", map[string]string{"name": "Jane Doe", "email": "jane@example.com"}).JSON(t, &c)
	e.Clock.Advance(time.Minute)
	doWithID(t, e, http.StatusOK, "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, "req-rename", map[string]string{"name": "Jane Smith"})
	e.Clock.Advance(time.Minute)
	doWithID(t, e, http.StatusOK, "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, "req-same", map[string]string{"name": "Jane Smith"})
	e.Clock.Advance(time.Minute)
	doWithID(t, e, http.StatusNoContent, "DELETE", "/v1/customers/"+c.ID, e.Acme.Key, "req-delete", nil)

	log := readAudit(t, e, e.Acme.Key, "")
	if got, want := actionsOf(log), []string{"customer.deleted", "customer.updated", "customer.updated", "customer.created"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("actions = %v, want %v", got, want)
	}
	del, rename, same, created := log.Items[0], log.Items[1], log.Items[2], log.Items[3]

	wantActor := store.AuditActor{Type: "api_key", ID: keyIDOf(t, e, e.Acme.Key), UserID: e.Acme.Owner.ID}
	if del.Actor != wantActor {
		t.Fatalf("actor = %+v, want %+v", del.Actor, wantActor)
	}
	if del.Target != (store.AuditTarget{Type: "customer", ID: c.ID}) || del.RequestID != "req-delete" {
		t.Fatalf("delete entry = %+v", del)
	}
	if !del.At.Equal(e.Clock.Now()) || del.Changes != nil {
		t.Fatalf("delete entry at %v, changes %v", del.At, del.Changes)
	}
	if rename.RequestID != "req-rename" || !rename.At.Equal(e.Clock.Now().Add(-2*time.Minute)) {
		t.Fatalf("rename entry = %+v", rename)
	}
	if want := (map[string]store.AuditChange{"name": {From: "Jane Doe", To: "Jane Smith"}}); rename.Changes == nil || !reflect.DeepEqual(*rename.Changes, want) {
		t.Fatalf("rename changes = %+v, want %+v", rename.Changes, want)
	}
	if same.Changes == nil || len(*same.Changes) != 0 {
		t.Fatalf("an update that changed nothing has changes %+v, want an empty set", same.Changes)
	}
	if created.Changes != nil || !created.At.Equal(apitest.Start) {
		t.Fatalf("create entry = %+v", created)
	}

	// On the wire, an update always has "changes" and a create never does.
	raw := e.Do("GET", "/v1/audit-events", e.Acme.Key, nil).Map(t)["items"].([]any)
	if _, ok := raw[2].(map[string]any)["changes"].(map[string]any); !ok {
		t.Fatalf("update entry has no changes object: %v", raw[2])
	}
	if _, ok := raw[3].(map[string]any)["changes"]; ok {
		t.Fatalf("create entry has changes: %v", raw[3])
	}
}

func TestAuditLogRecordsOnlySuccess(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	gia := e.CreateCustomer(e.Globex, "Gia", "gia@example.com")
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)

	for _, f := range []struct {
		name, method, path, key string
		body                    any
		want                    int
	}{
		{"duplicate email", "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane 2", "email": "JANE@example.com"}, http.StatusConflict},
		{"no name", "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "", "email": "x@example.com"}, http.StatusUnprocessableEntity},
		{"not JSON", "POST", "/v1/customers", e.Acme.Key, "{not json", http.StatusBadRequest},
		{"unknown customer", "PATCH", "/v1/customers/cus_nope", e.Acme.Key, map[string]string{"name": "X"}, http.StatusNotFound},
		{"viewer deletes", "DELETE", "/v1/customers/" + jane.ID, viewer, nil, http.StatusForbidden},
		{"another organization's customer", "DELETE", "/v1/customers/" + gia.ID, e.Acme.Key, nil, http.StatusNotFound},
		{"a read", "GET", "/v1/customers", e.Acme.Key, nil, http.StatusOK},
	} {
		if r := e.Do(f.method, f.path, f.key, f.body); r.Code != f.want {
			t.Fatalf("%s: %s, want %d", f.name, r, f.want)
		}
	}

	if got := actionsOf(readAudit(t, e, e.Acme.Key, "")); !reflect.DeepEqual(got, []string{"customer.created"}) {
		t.Fatalf("Acme's log = %v, want only its own create", got)
	}
	if _, ok := e.Store.Customer(e.Globex.ID, gia.ID); !ok {
		t.Fatal("another organization's customer was deleted")
	}
	if got := actionsOf(readAudit(t, e, e.Globex.Key, "")); !reflect.DeepEqual(got, []string{"customer.created"}) {
		t.Fatalf("Globex's log = %v", got)
	}
}

func TestAuditLogTeamAndKeys(t *testing.T) {
	e := apitest.New(t)
	user, _ := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)

	var inv store.Invite
	var k store.APIKey
	doWithID(t, e, http.StatusOK, "PATCH", "/v1/members/"+user.ID, e.Acme.Key, "req-role", map[string]string{"role": "admin"})
	doWithID(t, e, http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, "req-invite", map[string]string{"email": "new@acme.example", "role": "member"}).JSON(t, &inv)
	doWithID(t, e, http.StatusNoContent, "DELETE", "/v1/invites/"+inv.ID, e.Acme.Key, "req-revoke-invite", nil)
	doWithID(t, e, http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, "req-key", map[string]string{"name": "CI"}).JSON(t, &k)
	doWithID(t, e, http.StatusNoContent, "DELETE", "/v1/api-keys/"+k.ID, e.Acme.Key, "req-revoke-key", nil)
	doWithID(t, e, http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, "req-org", map[string]string{"name": "Acme Inc"})
	doWithID(t, e, http.StatusNoContent, "DELETE", "/v1/members/"+user.ID, e.Acme.Key, "req-remove", nil)

	raw := e.Do("GET", "/v1/audit-events", e.Acme.Key, nil)
	log := readAudit(t, e, e.Acme.Key, "")
	want := []string{"member.removed", "org.updated", "api_key.revoked", "api_key.created", "invite.revoked", "invite.created", "member.role_changed"}
	if got := actionsOf(log); !reflect.DeepEqual(got, want) {
		t.Fatalf("actions = %v, want %v", got, want)
	}
	byAction := map[string]store.AuditEvent{}
	for _, ev := range log.Items {
		byAction[ev.Action] = ev
	}
	if got := byAction["member.role_changed"]; got.Target != (store.AuditTarget{Type: "member", ID: user.ID}) || !reflect.DeepEqual(changedFields(got), []string{"role"}) {
		t.Fatalf("role change = %+v", got)
	}
	if got := (*byAction["member.role_changed"].Changes)["role"]; got.From != "member" || got.To != "admin" {
		t.Fatalf("role change = %+v", got)
	}
	if got := byAction["invite.created"]; got.Target != (store.AuditTarget{Type: "invite", ID: inv.ID}) {
		t.Fatalf("invite created = %+v", got)
	}
	if got := byAction["api_key.created"]; got.Target != (store.AuditTarget{Type: "api_key", ID: k.ID}) {
		t.Fatalf("key created = %+v", got)
	}
	if got := byAction["org.updated"]; got.Target != (store.AuditTarget{Type: "org", ID: e.Acme.ID}) || !reflect.DeepEqual(changedFields(got), []string{"name"}) {
		t.Fatalf("org updated = %+v", got)
	}
	if got := byAction["member.removed"]; got.Target != (store.AuditTarget{Type: "member", ID: user.ID}) || got.Changes != nil {
		t.Fatalf("member removed = %+v", got)
	}

	// The invite's token and the key's token are credentials; neither appears in the log.
	for _, secret := range []string{inv.Token, k.Token} {
		if strings.Contains(string(raw.Body), secret) {
			t.Fatalf("the audit log holds the credential %q", secret)
		}
	}
}

