cat > internal/store/audit.go <<'EOF'
package store

import (
	"sort"
	"time"
)

// AuditEvent is one entry in an organization's audit log: who (an API key and its member) did what to which object. Entries
// are only ever added; nothing changes or deletes one.
type AuditEvent struct {
	ID        string      `json:"id"`
	OrgID     string      `json:"org_id"`
	Action    string      `json:"action"` // for example "customer.updated"
	Actor     AuditActor  `json:"actor"`
	Target    AuditTarget `json:"target"`
	RequestID string      `json:"request_id"`
	At        time.Time   `json:"at"`
	// Changes is set on the entries of updates (nil otherwise); it is empty when no field's value changed.
	Changes *map[string]AuditChange `json:"changes,omitempty"`
}

// AuditActor is the API key that made a change and the member it acts for.
type AuditActor struct {
	Type   string `json:"type"` // "api_key"
	ID     string `json:"id"`
	UserID string `json:"user_id"`
}

// AuditTarget is the object a change was made to.
type AuditTarget struct {
	Type string `json:"type"`
	ID   string `json:"id"`
}

// AuditChange is one field's value before and after an update.
type AuditChange struct {
	From any `json:"from"`
	To   any `json:"to"`
}

// AuditFilter selects audit entries. Empty fields match everything. ActorID is a user ID or an API key ID.
type AuditFilter struct {
	Action   string
	TargetID string
	ActorID  string
}

// AddAuditEvent appends an entry to the log and returns it with its ID.
func (s *Store) AddAuditEvent(e AuditEvent) AuditEvent {
	s.mu.Lock()
	defer s.mu.Unlock()
	e.ID = s.newID("aud")
	s.audit = append(s.audit, e)
	return e
}

// AuditEvents returns an organization's audit entries that match f, newest first.
func (s *Store) AuditEvents(orgID string, f AuditFilter) []AuditEvent {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []AuditEvent{}
	for _, e := range s.audit {
		if e.OrgID != orgID {
			continue
		}
		if f.Action != "" && e.Action != f.Action {
			continue
		}
		if f.TargetID != "" && e.Target.ID != f.TargetID {
			continue
		}
		if f.ActorID != "" && e.Actor.ID != f.ActorID && e.Actor.UserID != f.ActorID {
			continue
		}
		out = append(out, e)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].At.Equal(out[j].At) {
			return out[i].At.After(out[j].At)
		}
		return out[i].ID > out[j].ID
	})
	return out
}
EOF
